	@Test
	void wildcardPlanFlattensBoundPlaneUnitsAndRestoresAnExistingBinding() {
		WildcardPlanes wildcard = new WildcardPlanes(new PageAdjacency(3, 5, true),
				new PageAdjacency(-1, 4, true));
		wildcard.bind(1);

		LmdbNativeKernelPartitions.PartitionPlan plan = LmdbNativeKernelPartitions.planWildcard(6, wildcard, true,
				true);

		assertEquals(2, plan.planeCount());
		assertEquals(7L, plan.unitCount());
		assertEquals(LmdbNativeKernelPartitions.UnitKind.PAGE, plan.plane(0).kind());
		assertEquals(3L, plan.plane(0).unitCount());
		assertEquals(LmdbNativeKernelPartitions.UnitKind.ROOT_ORDINAL, plan.plane(1).kind());
		assertEquals(4L, plan.plane(1).unitCount());
		assertEquals(1, wildcard.boundPredicateOrdinal());
		List<LmdbNativeKernelPartitions.PartitionSegment> split = segments(plan, 2L, 5L);
		assertEquals(2, split.size());
		assertEquals(0, split.get(0).predicateOrdinal());
		assertEquals(2L, split.get(0).from());
		assertEquals(3L, split.get(0).to());
		assertEquals(1, split.get(1).predicateOrdinal());
		assertEquals(0L, split.get(1).from());
		assertEquals(2L, split.get(1).to());
	}

