	@Test
	void wildcardPageWindowBindsTheSelectedPlaneBeforeOpeningItsPages() {
		WildcardPlanes wildcard = new WildcardPlanes(new PageAdjacency(2, 3, true),
				new PageAdjacency(4, 3, true));
		wildcard.bind(0);
		LmdbNativeKernelPartitions.WildcardPageWindow window = new LmdbNativeKernelPartitions.WildcardPageWindow(
				wildcard, 1, 2, 4);

		window.bind(0);
		assertEquals(0, window.boundPredicateOrdinal());
		try (AdjacencyPageCursor pages = window.openPageCursor()) {
			assertTrue(pages.advance());
			assertEquals(2L, ((Pages) pages).firstPageOrdinal());
			assertTrue(pages.advance());
			assertEquals(3L, ((Pages) pages).firstPageOrdinal());
			assertFalse(pages.advance());
		}
		assertEquals(1, wildcard.boundPredicateOrdinal());
	}

	@Test
	void mergedWildcardRootWindowsCoverOneLargePredicateWithoutOverlap() {
		WildcardPlanes wildcard = new WildcardPlanes(new PageAdjacency(-1, 1001, true));
		LmdbNativeKernelPartitions.PartitionPlan plan = LmdbNativeKernelPartitions.planWildcardPredicate(5, wildcard,
				100L, true, true);

		assertEquals(LmdbNativeKernelPartitions.UnitKind.ROOT_ORDINAL, plan.plane(0).kind());
		assertEquals(1001L, plan.unitCount());
		List<Long> seen = new ArrayList<>();
		for (long[] range : LmdbNativeKernelPartitions.ranges(plan.unitCount(), 2, 2)) {
			for (LmdbNativeKernelPartitions.PartitionSegment segment : segments(plan, range[0], range[1])) {
				LmdbNativeKernelPartitions.WildcardPredicateWindow window = new LmdbNativeKernelPartitions.WildcardPredicateWindow(
						wildcard, segment.predicateOrdinal(), segment.predicateOrdinal() + 1L, segment.from(),
						segment.to());
				try (KeyRunCursor roots = window.openKeyRunCursor()) {
					while (roots.advance()) {
						seen.add(roots.key());
					}
				}
			}
		}

		assertEquals(1001, seen.size());
		for (int ordinal = 0; ordinal < seen.size(); ordinal++) {
			assertEquals((long) ordinal, seen.get(ordinal));
		}
	}

	@Test
	void mergedWildcardRootWindowFeedsProjectionCursorOnlyItsExactRootSubset() {
		RootWildcard wildcard = new RootWildcard(new long[] { 11L, 22L, 33L, 44L },
				new long[] { 101L, 102L, 103L, 104L });
		LmdbNativeKernelPartitions.WildcardPredicateWindow window = new LmdbNativeKernelPartitions.WildcardPredicateWindow(
				wildcard, 0, 1, 1, 3);
		assertNull(window.openPageCursor(), "a root window must select the exact run cursor path");
		assertNull(window.openPageCursor(0L, 0L), "a root window must decline every page range");
		List<Long> roots = new ArrayList<>();
		KernelProjectionCursor.Program program = new KernelProjectionCursor.Program() {
			@Override
			public boolean enter(int grain, long predicate, KernelAdjacencyCursor cursor) {
				if (grain == KernelProjectionCursor.ROOT) {
					assertNotNull(cursor);
					roots.add(cursor.rootId());
				}
				return true;
			}

			@Override
			public void restore(int grain) {
			}
		};

		long emittedWeight = 0L;
		try (KernelProjectionCursor projection = KernelProjectionCursor.open(
				KernelProjectionCursor.wildcard(window), program, 1 << KernelProjectionCursor.QUAD,
				1 << KernelProjectionCursor.ROOT, false, false, 0L, false, null, null, 0)) {
			assertNotNull(projection);
			while (projection.advance()) {
				if (projection.grain() == KernelProjectionCursor.QUAD) {
					emittedWeight = Math.addExact(emittedWeight, projection.weight());
				}
			}
		}

		assertEquals(List.of(22L, 33L), roots);
		assertEquals(2L, emittedWeight, "the bounded root window must contribute exactly two physical quads");
	}

	private static List<LmdbNativeKernelPartitions.PartitionSegment> segments(
			LmdbNativeKernelPartitions.PartitionPlan plan, long from, long to) {
		List<LmdbNativeKernelPartitions.PartitionSegment> segments = new ArrayList<>();
		plan.forEachSegment(from, to, (view, predicate, kind, segmentFrom, segmentTo) -> segments.add(
				new LmdbNativeKernelPartitions.PartitionSegment(view, predicate, kind, segmentFrom, segmentTo)));
		return segments;
	}

