	private static final class RootWildcard implements NativeLmdbQuerySource.WildcardAdjacency {
		private static final long NOT_FOUND = -1L;

		private final long[] roots;
		private final long[] neighbors;
		private int bound = -1;

		private RootWildcard(long[] roots, long[] neighbors) {
			if (roots.length != neighbors.length) {
				throw new IllegalArgumentException("root and neighbor arrays differ in length");
			}
			this.roots = roots;
			this.neighbors = neighbors;
		}

		@Override
		public int predicateCount() {
			return 1;
		}

		@Override
		public long predicateAt(int predicateOrdinal) {
			if (predicateOrdinal != 0) {
				throw new IndexOutOfBoundsException("predicate ordinal");
			}
			return 900L;
		}

		@Override
		public void bind(int predicateOrdinal) {
			if (predicateOrdinal != 0) {
				throw new IndexOutOfBoundsException("predicate ordinal");
			}
			bound = 0;
		}

		@Override
		public int boundPredicateOrdinal() {
			return bound;
		}

		@Override
		public long keyCount() {
			checkBound();
			return roots.length;
		}

		@Override
		public long maximumKey() {
			return roots.length == 0 ? 0L : roots[roots.length - 1];
		}

		@Override
		public long keyAt(long keyOrdinal) {
			checkBound();
			return roots[Math.toIntExact(keyOrdinal)];
		}

		@Override
		public int findBatch(long[] keys, int keyOffset, int count, long[] runHandles, int runOffset) {
			checkBound();
			int found = 0;
			for (int lane = 0; lane < count; lane++) {
				long wanted = keys[keyOffset + lane];
				long handle = NOT_FOUND;
				for (int root = 0; root < roots.length; root++) {
					if (roots[root] == wanted) {
						handle = root + 1L;
						found++;
						break;
					}
				}
				runHandles[runOffset + lane] = handle;
			}
			return found;
		}

		public long find(long key) {
			long[] keys = { key };
			long[] handles = { NOT_FOUND };
			findBatch(keys, 0, 1, handles, 0);
			return handles[0];
		}

		@Override
		public long size(long runHandle) {
			if (runHandle <= 0L || runHandle > roots.length) {
				throw new IllegalArgumentException("invalid run handle");
			}
			return 1L;
		}

		@Override
		public long neighborAt(long runHandle, long runOffset) {
			return neighbors[Math.toIntExact(runHandle - 1L)];
		}

		@Override
		public long contextAt(long runHandle, long runOffset) {
			return 7L;
		}

		@Override
		public KeyRunCursor openKeyRunCursor() {
			return openKeyRunCursor(0L, roots.length);
		}

		@Override
		public KeyRunCursor openKeyRunCursor(long fromOrdinal, long toOrdinal) {
			checkBound();
			if (fromOrdinal < 0L || toOrdinal < fromOrdinal || toOrdinal > roots.length) {
				throw new IllegalArgumentException("invalid root window");
			}
			return new KeyRunCursor() {
				private int ordinal = Math.toIntExact(fromOrdinal) - 1;

				@Override
				public boolean advance() {
					return ++ordinal < toOrdinal;
				}

				@Override
				public long key() {
					return roots[ordinal];
				}

				@Override
				public long runHandle() {
					return ordinal + 1L;
				}

				@Override
				public long runSize() {
					return 1L;
				}

				@Override
				public long neighborAt(long runOffset) {
					return neighbors[ordinal];
				}

				@Override
				public long contextAt(long runOffset) {
					return 7L;
				}

				@Override
				public int copyNeighbors(long runOffset, int length, long[] target, int targetOffset) {
					if (runOffset != 0L || length == 0) {
						return 0;
					}
					target[targetOffset] = neighbors[ordinal];
					return 1;
				}

				@Override
				public int copyContexts(long runOffset, int length, long[] target, int targetOffset) {
					if (runOffset != 0L || length == 0) {
						return 0;
					}
					target[targetOffset] = 7L;
					return 1;
				}
			};
		}

		@Override
		public void close() {
		}

		private void checkBound() {
			if (bound != 0) {
				throw new IllegalStateException("wildcard is not bound");
			}
		}
	}

	private static final class Pages implements AdjacencyPageCursor {
		private final int to;
		private final boolean contexts;
		private int page;

		private Pages(int from, int to, boolean contexts) {
			this.page = from;
			this.to = to;
			this.contexts = contexts;
		}

		@Override
		public boolean advance() {
			return page < to && ++page >= 0;
		}

		int firstPageOrdinal() {
			return page - 1;
		}

		@Override
		public int rowCount() {
			return 1;
		}

		@Override
		public int fiberCount() {
			return 1;
		}

		@Override
		public long quadCount() {
			return 1L;
		}

		@Override
		public long firstRow() {
			return 10L + firstPageOrdinal();
		}

		@Override
		public long rowAt(int rowIndex) {
			return firstRow();
		}

		@Override
		public long rowQuadCount(int rowIndex) {
			return 1L;
		}

		@Override
		public int rowFiberCount(int rowIndex) {
			return 1;
		}

		@Override
		public long neighborAt(int rowIndex, int localFiber) {
			return 20L;
		}

		@Override
		public long fiberContextCount(int rowIndex, int localFiber) {
			return 1L;
		}

		@Override
		public int copyRowFibers(int rowIndex, int fromFiber, int length, long[] neighborTarget, int neighborOffset,
				long[] multiplicityTarget, int multiplicityOffset) {
			if (fromFiber != 0 || length == 0) {
				return 0;
			}
			neighborTarget[neighborOffset] = neighborAt(rowIndex, 0);
			multiplicityTarget[multiplicityOffset] = 1L;
			return 1;
		}

		@Override
		public boolean supportsContextAccess() {
			return contexts;
		}

		@Override
		public boolean uniformRowTermKind() {
			return true;
		}

		@Override
		public boolean uniformRowLiteralDatatype() {
			return false;
		}

		@Override
		public boolean uniformNeighborTermKind() {
			return true;
		}

		@Override
		public boolean uniformNeighborLiteralDatatype() {
			return false;
		}
	}
